const cache = new Map();
function readOrder(user, id) {
  if (cache.has(id)) return cache.get(id);
  const result = { id, owner: user };
  cache.set(id, result);
  return result;
}
console.log(readOrder('alice', 'o1').owner);
console.log(readOrder('bob', 'o1').owner);

